using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("AsyncAwait")]
    [TestClass]
    public class RJIT_CR_AA_I_00005 : MsTestBase   
    {
        /*
         * Following the RJIT_CR_AA_C_00005 code rule, which advises against using nested Task<Task> structures in async methods, is essential for maintaining clean, efficient, and understandable asynchronous C# code.
         */
        [TestMethod]
        public void Avoid_Nested_Task()
        {
            var nestedTaskReturnTypes = (from @interfaces in Interfaces
                                         from @method in @interfaces.Methods
                                         where method.ReturnParameter.Contains("Task<Task")
                                         select new
                                         {
                                             Error = $@"
Avoid returning Task<Task> in async methods. Consider awaiting the nested task or changing the method's return type to Task.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Interface:  {@interfaces.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample: {method.MethodValue.Split(Environment.NewLine)[0].Replace(method.ReturnParameter, $"{method.ReturnParameter.Replace("Task<Task", "Task").TrimEnd('>')}>")}
Suggested Fix: Use 'await' inside the method or change the return type to directly return the result inside the nested Task.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                         }).ToImmutableList();

            Assert.IsTrue(nestedTaskReturnTypes.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_AA_00005

Avoid using nested Task structures in async methods. Findings: '{nestedTaskReturnTypes.Count}': {Environment.NewLine}{nestedTaskReturnTypes.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
